import requests

def download_report(url: str) -> bytes:
    try:
        response = requests.get(
            url,
            timeout=(3.05, 10),  # connect, read
        )
        response.raise_for_status()
        return response.content
    except requests.exceptions.ConnectTimeout as exc:
        raise RuntimeError("connection could not be established in time") from exc
    except requests.exceptions.ReadTimeout as exc:
        raise RuntimeError("server stopped delivering response bytes in time") from exc
